    &lt;div class="alert alert-success"&gt;&lt;h3&gt;EQUIPO REGISTRADO&lt;/h3&gt;&lt;/div&gt;
  &lt;?php } else { ?&gt;
    &lt;div class="alert alert-danger"&gt;
      &lt;h3&gt;NO SE PUDO REGISTRAR&lt;/h3&gt;
      &lt;ul class="list-unstyled mb-0"&gt;
        &lt;?php foreach ($errores as $e) { echo "&lt;li&gt;$e&lt;/li&gt;"; } ?&gt;
